function App() {
  const [page, setPage] = React.useState("home");
  const [selectedTask, setSelectedTask] = React.useState(null);

  function goTo(nextPage) {
    setPage(nextPage);
    setSelectedTask(null);
  }

  return (
    <>
      <nav>
        <button
          onClick={() => goTo("home")}
          aria-current={page === "home" ? "page" : undefined}
        >
          Home
        </button>
        <button
          onClick={() => goTo("tasks")}
          aria-current={page === "tasks" ? "page" : undefined}
        >
          Tasks
        </button>
        <button
          onClick={() => goTo("about")}
          aria-current={page === "about" ? "page" : undefined}
        >
          About
        </button>
      </nav>

      <main>
        {page === "home" && <h1>Welcome</h1>}

        {page === "tasks" && (
          <>
            <h1>Tasks</h1>
            <ul>
              <li>
                <button onClick={() => setSelectedTask("Buy milk")}>Buy milk</button>
              </li>
              <li>
                <button onClick={() => setSelectedTask("Write tests")}>Write tests</button>
              </li>
            </ul>
            {selectedTask && (
              <p data-testid="detail">Task: {selectedTask}</p>
            )}
          </>
        )}

        {page === "about" && <h1>About</h1>}
      </main>
    </>
  );
}

